import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function readPageFile(e){return readFileSync(resolve(__dirname,"../../frontend/padma-vibhushan-explorer",e),"utf-8")}function readLandingFile(){return readFileSync(resolve(__dirname,"../../frontend/awards-of-india-explorer/index.html"),"utf-8")}describe("Padma Vibhushan Explorer — Page Structure",()=>{let e;beforeAll(()=>{e=readPageFile("index.html")}),it("contains hero title and badge info",()=>{expect(e).toContain('class="pv-hero-title"'),expect(e).toContain("Padma Vibhushan Explorer"),expect(e).toContain("Second-Highest Civilian Honour")}),it("contains all required content sections",()=>{["history","eligibility","medal-design","selection","categories","recipients","timeline","faqs","gallery"].forEach(t=>{expect(e).toContain(`id="${t}"`),expect(e).toContain(`data-tab="${t}"`)})}),it("contains notable recipients",()=>{expect(e).toContain("Satyajit Ray"),expect(e).toContain("Pandit Ravi Shankar"),expect(e).toContain("Ratan Tata"),expect(e).toContain("MC Mary Kom")}),it("links shared stylesheet, page stylesheet, and script",()=>{expect(e).toContain('href="../../styles.css"'),expect(e).toContain('href="style.css"'),expect(e).toContain('src="script.js"')})}),describe("Padma Vibhushan Explorer — Assets & Script",()=>{it("includes a non-empty stylesheet",()=>{const e=readPageFile("style.css");expect(e.length).toBeGreaterThan(1e3),expect(e).toContain(".pv-hero")}),it("includes valid interactive script",()=>{const e=readPageFile("script.js");expect(e).toContain("initTabs"),expect(e).toContain("initFaqAccordion")})}),describe("Padma Vibhushan Explorer — Landing Page Integration",()=>{it("is linked on the Awards of India Explorer Landing Page",()=>{const e=readLandingFile();expect(e).toContain("Padma Vibhushan"),expect(e).toContain("../padma-vibhushan-explorer/index.html")})});